create or replace function public.generate_rent_charges(p_relationship_id uuid,p_through_date date default current_date) returns setof public.charges language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; m date; last_month date; period_start date; period_end date; due_date date; term public.rental_term_versions; created public.charges; days_in_month int; begin select * into r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status not in ('ACTIVE','ENDING','ENDED') then raise exception 'RENTAL_NOT_CHARGEABLE'; end if; if r.tracking_start_date is null or r.payment_day is null then raise exception 'RENTAL_BILLING_CONFIGURATION_INCOMPLETE'; end if; if p_through_date < r.tracking_start_date then return; end if; m:=date_trunc('month',r.tracking_start_date)::date; last_month:=date_trunc('month',least(p_through_date,coalesce(r.actual_end_date,p_through_date)))::date; while m<=last_month loop period_start:=greatest(m,r.tracking_start_date); period_end:=(m+interval '1 month'-interval '1 day')::date; if r.actual_end_date is not null then period_end:=least(period_end,r.actual_end_date); end if; select * into term from public.rental_term_versions t where t.rental_relationship_id=r.id and period_start between t.effective_from and coalesce(t.effective_until,'infinity'::date) order by t.version_number desc limit 1; if found then days_in_month:=extract(day from (m+interval '1 month'-interval '1 day'))::int; due_date:=m+(least(r.payment_day,days_in_month)-1); insert into public.charges(administration_id,rental_relationship_id,charge_type,origin,description,period_start,period_end,due_date,amount,currency,source_type,source_id) values(r.administration_id,r.id,'RENT','SYSTEM','Canon de arrendamiento',period_start,period_end,due_date,term.rent_amount,'COP','RENT_TERM_VERSION',term.id) on conflict (rental_relationship_id,source_type,source_id,period_start) where source_type is not null and source_id is not null and period_start is not null do nothing returning * into created; if found then return next created; end if; end if; m:=(m+interval '1 month')::date; end loop; return; end $$;